import{_ as i,a0 as o,w as u,s as r,ao as p,I as e,x as n,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux上最先進的免費賽車遊戲：StuntRally 2.4 | LCTT x X-CMD","titleTemplate":false,"description":"Linux上最先進的免費賽車遊戲：StuntRally 2.4 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上最先進的免費賽車遊戲：StuntRally 2.4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上最先進的免費賽車遊戲：StuntRally 2.4 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux","title":"Linux上最先進的免費賽車遊戲：StuntRally 2.4","tag":"201408","desc":""},"relativePath":"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux.md","filePath":"[post].md"}'),d={name:"201408/20140811 StuntRally 2.4 Is the Most Advanced Free Racing Game on Linux.md"};function m(f,t,x,y,R,S){const l=o("Link");return u(),r("div",null,[t[18]||(t[18]=p('<h1 id="linux上最先進的免費賽車遊戲-stuntrally-2-4" tabindex="-1">Linux上最先進的免費賽車遊戲：StuntRally 2.4 <a class="header-anchor" href="#linux上最先進的免費賽車遊戲-stuntrally-2-4" aria-label="Permalink to “Linux上最先進的免費賽車遊戲：StuntRally 2.4”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345-2.jpg" alt="StuntRally"> StuntRally</p><p><strong>StuntRally，免費的賽車遊戲，擁有超過150個賽道和大量的車型，剛剛發佈2.4版本，並帶來大量的更新和新功能。</strong></p><p>這個遊戲使用了多項技術， 例如 Vdrift、物理引擎 bullet、面向對象圖形渲染引擎 OGRE、 網格的渲染優化 PagedGeometry 和 MyGUI 等等，不一一列舉，開發者將其全部整合在一起構造了一個非常複雜和有趣的賽車遊戲.</p><p>玩家可以在147個賽道和26個不同的場景中游戲，總計有四個小時的車程時間。在如此多的選擇下，你要知道，而StuntRally是完全免費的！</p><p>其他功能包括在幽靈駕駛（可以跟蹤你的車子在賽道上的最佳瞬間），賽道幽靈（賽道上的最佳駕駛，一個綠幽靈賽車，可以出現在所有軌道），回放（記錄你的駕駛過程，並可以從其它的攝像頭角度查看），許多的教程，幾個總冠軍盃賽，一些挑戰賽，分屏賽車，和多人遊戲。</p><p>最重要的是，開發商還提供了一個軌道編輯器，允許用户實時編輯道路節點及其參數，改變所有的賽道參數，調整地形生成器，甚至修改駕駛中的汽車的屬性。</p><p>根據更新日誌，添加了6個新的地圖，刪除了12箇舊關卡，更新了一些賽道，增加了兩個名為Crystals 和 GreeceWhite的場景，實現了太空飛船式氣墊船，一半的賽道添加了新的天空紋理貼圖，一些賽道上的靜態景物現在可以用了，汽車屬性頁有了狀態條、速度圖，並添加了一個短列表視圖。</p><p>同時，字體現在他們已重新調整得更大了，增加了包括勝利、失敗、過圈最佳時間和故障檢測排除等聲音，已修復了多人遊戲中用户暱稱出現兩次的問題，在一些賽道實現了地形、濃霧、水體的影響，關卡編輯器已經做了一些改進，汽車轉向控制進行了改進，修復了遊戲中的汽車表面調整窗口。</p>',9)),e("p",null,[t[1]||(t[1]=n("關於StuntRally更多最新消息可以參考 ",-1)),s(l,{href:"https://code.google.com/p/vdrift-ogre/wiki/VersionHistory"},{default:a(()=>[...t[0]||(t[0]=[n("通告",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[19]||(t[19]=e("p",null,"下載 StuntRally 2.4:",-1)),e("ul",null,[e("li",null,[s(l,{href:"http://sourceforge.net/projects/stuntrally/files/2.4/StuntRally-2.4-linux64.tar.xz/download"},{default:a(()=>[...t[3]||(t[3]=[n("Stunt Rally 2.4 tar.xz",-1)])]),_:1}),t[4]||(t[4]=n("[binary] [735 MB]",-1))])]),t[20]||(t[20]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=n("via: ",-1)),s(l,{href:"http://news.softpedia.com/news/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345.shtml"},{default:a(()=>[...t[5]||(t[5]=[n("http://news.softpedia.com/news/StuntRally-2-4-Is-the-Most-Advance-Free-Racing-Game-on-Linux-454345.shtml",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("作者：",-1)),s(l,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:a(()=>[...t[7]||(t[7]=[n("Silviu Stahie",-1)])]),_:1}),t[11]||(t[11]=n(" 譯者：",-1)),s(l,{href:"https://github.com/fbigun"},{default:a(()=>[...t[8]||(t[8]=[n("fbigun",-1)])]),_:1}),t[12]||(t[12]=n(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=n("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原創翻譯，",-1)),s(l,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[n("Linux中國",-1)])]),_:1}),t[17]||(t[17]=n(" 榮譽推出",-1))])])}const C=i(d,[["render",m]]);export{T as __pageData,C as default};
